import {ACTION_CARDS} from './basic-actions.js';
import {intelligenceTargets,intelligenceCandidates,copyAbilityPreview} from './intelligence.js';
const names={US:'美国',CN:'中国',EU:'欧盟',RU:'俄罗斯'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderInspectOpponent(s){return `<p>选择另一位玩家，查看其手牌，再决定是否复制一张能力牌。</p><label>查看玩家<select id="sequence-spy-player">${intelligenceTargets(s).map(player=>`<option value="${player}">${names[player]} · 手牌${s.players[player].hand.length}张 · 可复制已出牌${intelligenceCandidates(s,player).filter(x=>x.zone==='played').length}张</option>`).join('')}</select></label><button id="sequence-resolve">查看此玩家的手牌</button>`;}
export function renderCopyAbility(s,step,cards){const candidates=intelligenceCandidates(s,step.player);return `<p>正在查看${names[step.player]}。可复制其一张手牌或正面打出的能力牌；由你支付费用、选择目标并获得效果，对方原牌保留。</p>${['hand','played'].map(zone=>`<fieldset><legend>${names[step.player]} · ${zone==='hand'?'手牌':'已打出的能力牌'}</legend><div class="growth-choice-grid">${candidates.filter(x=>x.zone===zone).map(x=>`<label class="growth-choice"><img src="${esc(cards[x.cardId]?.image)}" alt="${esc(ACTION_CARDS[x.cardId].name)}" loading="lazy"><span><input type="radio" name="intelligence-copy" data-intelligence-card="${x.cardId}" data-intelligence-zone="${zone}"> ${esc(ACTION_CARDS[x.cardId].name)}</span></label>`).join('')||'<p>没有可复制的牌。</p>'}</div></fieldset>`).join('')}<p id="sequence-copy-preview" aria-live="polite"></p><button id="sequence-resolve">复制所选牌的效果</button><button id="sequence-skip">只查看，不复制</button>`;}
export function readCopyAbility(){const el=document.querySelector('[data-intelligence-card]:checked');return {targetCard:el?.dataset.intelligenceCard,zone:el?.dataset.intelligenceZone};}
export function updateCopyAbility(s,step){try{const r=copyAbilityPreview(s,readCopyAbility(),step);document.querySelector('#sequence-copy-preview').textContent=`将按${r.name}的顺序继续结算。${r.trashSelf?'你本次打出的情报窃取会移出游戏，对方原牌保留。':'复制本身不消耗额外出牌额度；后续费用依牌面支付。'}`;document.querySelector('#sequence-resolve').disabled=false;}catch(error){document.querySelector('#sequence-copy-preview').textContent=error.message;document.querySelector('#sequence-resolve').disabled=true;}}
